const items = $input.all();
return items.slice(0, 40).map(item => {
  const raw = item.json.title || '';
  const colonIdx = raw.indexOf(':');
  const company = colonIdx > 0 ? raw.substring(0, colonIdx).trim() : '';
  const title = colonIdx > 0 ? raw.substring(colonIdx + 1).trim() : raw;
  return {
    json: {
      job_title: title,
      company: company,
      job_url: item.json.link || '',
