      posted_date: job.createdAt || '',
      tags: Array.isArray(job.categories) ? job.categories.join(', ') : ''
    }
  };
});

const items = $input.all();
return items.slice(0, 30).map(item => ({
  json: {
    job_title: (item.json.title || '').replace(/<[^>]*>/g, '').trim(),
    company: item.json.author || item.json.creator || '',
    job_url: item.json.link || '',
