    posted_date: item.json.isoDate || item.json.pubDate || '',
    tags: ''
  }
}));

// YC Work at Startup may require login for structured data.
// Returns empty array as placeholder - configure browser automation or
// use their unofficial API with authentication for production.
const data = $input.first().json;
const jobs = Array.isArray(data) ? data : (data.jobs || data.results || []);
return jobs.slice(0, 30).map(job => ({
  json: {
    job_title: job.title || job.role || '',
    company: (job.company && job.company.name) ? job.company.name : (job.companyName || ''),
    job_url: job.url || ('https://www.workatastartup.com/jobs/' + (job.id || '')),
    source: 'YC Work at Startup',
    location_text: job.location || 'Remote',
    salary: job.compensation || job.salary || '',
    description: (job.description || job.body || '').replace(/<[^>]*>/g, ' ').trim(),
    posted_date: job.createdAt || job.created_at || '',
    tags: Array.isArray(job.tags) ? job.tags.join(', ') : ''
  }
}));

// Wellfound requires GraphQL auth - this extracts whatever is returned.
// For production: set up Wellfound API credentials or use Apify scraper.
const data = $input.first().json;
const jobs = data.jobs || data.results || data.data || [];
if (!Array.isArray(jobs) || jobs.length === 0) return [];
return jobs.slice(0, 30).map(job => ({
  json: {
    job_title: job.title || job.role || '',
    company: (job.company && job.company.name) ? job.company.name : (job.startupName || ''),
    job_url: job.url || job.link || '',
    source: 'Wellfound',
    location_text: job.locationNames || job.location || 'Remote',
    salary: job.salary || job.compensation || '',
    description: (job.description || '').replace(/<[^>]*>/g, ' ').trim(),
    posted_date: job.liveStartAt || job.postedAt || '',
    tags: Array.isArray(job.skills) ? job.skills.join(', ') : ''
  }
}));

// Otta may require authentication for full access.
// This handles both authenticated and unauthenticated responses.
const data = $input.first().json;
const jobs = (data.data && data.data.jobs && data.data.jobs.nodes) ? data.data.jobs.nodes : (data.jobs || []);
if (!Array.isArray(jobs) || jobs.length === 0) return [];
return jobs.slice(0, 30).map(job => ({
  json: {
    job_title: job.title || '',
    company: (job.company && job.company.name) ? job.company.name : '',
    job_url: job.url || ('https://app.otta.com/jobs/' + (job.id || '')),
    source: 'Otta',
    location_text: Array.isArray(job.locations) ? job.locations.map(l => l.name).join(', ') : 'Remote',
    salary: job.salary || '',
    description: (job.description || '').replace(/<[^>]*>/g, ' ').trim(),
    posted_date: '',
    tags: ''
  }
}));

const allItems = $input.all();
const existingUrls = new Set();
const existingKeys = new Set();
const batchUrls = new Set();
const batchKeys = new Set();
const newJobs = [];

// First pass: collect existing URLs and keys from Google Sheets data
for (const item of allItems) {
  if (item.json._from_sheets === true) {
    const url = (item.json.job_url || '').trim().toLowerCase();
    const key = [(item.json.company || ''), (item.json.job_title || '')].join('|').toLowerCase().trim();
    if (url) existingUrls.add(url);
    if (key && key !== '|') existingKeys.add(key);
  }
}

// Second pass: filter out duplicates from incoming jobs
for (const item of allItems) {
  if (item.json._from_sheets === true) continue;
  const url = (item.json.job_url || '').trim().toLowerCase();
  const key = [(item.json.company || ''), (item.json.job_title || '')].join('|').toLowerCase().trim();
  if (!url && !item.json.job_title) continue;
  if (existingUrls.has(url) || existingKeys.has(key)) continue;
  if (batchUrls.has(url) || batchKeys.has(key)) continue;
  if (url) batchUrls.add(url);
  if (key && key !== '|') batchKeys.add(key);
  newJobs.push({
    json: {
      ...item.json,
      date_found: new Date().toISOString().split('T')[0],
      job_id: url || key
    }
  });
}

return newJobs;

const job = $input.item.json;
const fullText = [job.job_title, job.description, job.location_text, job.tags].join(' ').toLowerCase();

const rejectTerms = [
  'us only', 'usa only', 'united states only', 'us residents only', 'us-based only',
  'canada only', 'uk only', 'united kingdom only', 'eu only', 'europe only',
  'australia only', 'new zealand only', 'must be based in', 'must live in',
  'must reside in', 'must be located in', 'authorized to work in the us',
  'must be authorized to work', 'work authorization required',
  'local work permit required', 'hybrid role', 'hybrid position',
  'in-office', 'onsite', 'on-site required', 'office required',
  'remote within the us', 'remote in the us', 'us remote only',
  'remote only within', 'fixed est hours', 'fixed pst hours',
  'fixed eastern time', 'security clearance required', 'us citizenship'
];

const keepTerms = [
  'worldwide remote', 'work from anywhere', 'global remote', 'anywhere in the world',
  'remote worldwide', 'open to all countries', 'apac remote', 'asia pacific',
  'international contractors', 'international applicants welcome',
  'hires via deel', 'hires via remote.com', 'hires via oyster',
  'employer of record', 'eor supported', 'b2b contractor', 'open to contractors',
  'remote-first', 'distributed team', 'no location restriction', 'location independent',
  'globally remote', 'fully distributed'
];

const hasReject = rejectTerms.some(t => fullText.includes(t));
const hasKeep = keepTerms.some(t => fullText.includes(t));

let hard_filter_passed, hard_filter_reason;

if (hasReject && !hasKeep) {
  hard_filter_passed = false;
  const found = rejectTerms.find(t => fullText.includes(t));
  hard_filter_reason = 'Rejected: contains "' + found + '"';
} else {
  hard_filter_passed = true;
  if (hasKeep) {
    const found = keepTerms.find(t => fullText.includes(t));
    hard_filter_reason = 'Passed: "' + found + '"';
  } else {
    hard_filter_reason = 'Passed: no location restriction detected';
  }
}

return [{ json: { ...job, hard_filter_passed, hard_filter_reason } }];

const job = $input.item.json;
const title = job.job_title || 'Unknown Title';
const company = job.company || 'Unknown Company';
const location = job.location_text || '';
const salary = job.salary || 'Not listed';
const tags = job.tags || '';
const description = (job.description || '').slice(0, 3000);

const systemPrompt = `You are filtering remote jobs for Jerry, who lives in Taiwan.

The most important rule: Jerry must be able to work this job while physically based in Taiwan.

Do not pass the job only because it says 'remote.'

REJECT if:
- Requires worker to live in US, Canada, UK, EU, Europe, Australia, or any specific country outside Taiwan
- Requires local work authorization outside Taiwan
- Is hybrid, onsite, or remote within one country only
- Requires fixed hours that force Jerry to work through the night in Taiwan (e.g., must overlap US East or US West business hours full-time)

KEEP only if at least one of these is true:
- Says worldwide remote, work from anywhere, global remote, or APAC remote
- Allows international contractors or accepts people based anywhere
- Company hires through EOR, Deel, Remote.com, Oyster, or contractor agreement
- No location restriction is mentioned

Respond ONLY with this exact JSON — no extra text:
{
  "taiwan_eligible": "yes",
  "reason": "brief explanation under 20 words",
  "location_risk": "low",
  "timezone_risk": "low",
  "contractor_possible": "yes",
  "decision": "keep"
}

taiwan_eligible: yes / no / unclear
contractor_possible: yes / no / unclear
location_risk: low / medium / high
timezone_risk: low / medium / high
decision: keep / reject / manual_check`;

const userMessage = `Job Title: ${title}
Company: ${company}
Location: ${location}
Salary: ${salary}
Tags: ${tags}

Job Description:
${description}`;

const apiBody = JSON.stringify({
  model: 'claude-opus-4-7',
  max_tokens: 400,
  system: systemPrompt,
  messages: [{ role: 'user', content: userMessage }]
});

return [{ json: { ...job, _api_body: apiBody } }];

const aiHttpResponse = $input.item.json;
// Recover original job data from the node before the HTTP request
const originalJob = $('Prepare AI Request').item.json;

let aiText = '';
try {
  if (Array.isArray(aiHttpResponse.content) && aiHttpResponse.content[0]) {
    aiText = aiHttpResponse.content[0].text || '';
  } else if (typeof aiHttpResponse === 'string') {
    aiText = aiHttpResponse;
  }
} catch(e) { aiText = JSON.stringify(aiHttpResponse); }

let aiData = {
  taiwan_eligible: 'unclear',
  reason: 'Could not parse AI response',
  location_risk: 'medium',
  timezone_risk: 'medium',
  contractor_possible: 'unclear',
  decision: 'manual_check'
};

try {
  const jsonMatch = aiText.match(/\{[\s\S]*?\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    Object.assign(aiData, parsed);
  }
} catch(e) {}

// Strip internal fields before passing forward
const { _api_body, _from_sheets, hard_filter_passed, hard_filter_reason, ...cleanJob } = originalJob;

return [{
  json: {
    ...cleanJob,
    taiwan_eligible: String(aiData.taiwan_eligible || 'unclear'),
    taiwan_reason: String(aiData.reason || ''),
    location_risk: String(aiData.location_risk || 'medium'),
    timezone_risk: String(aiData.timezone_risk || 'medium'),
    contractor_possible: String(aiData.contractor_possible || 'unclear'),
    decision: String(aiData.decision || 'manual_check')
  }
}];

const job = $input.item.json;
const fullText = [job.job_title, job.description, job.location_text, job.tags].join(' ').toLowerCase();
const titleLower = (job.job_title || '').toLowerCase();

// Taiwan eligibility score (0–40)
let score_taiwan = 20;
if (job.taiwan_eligible === 'yes') {
  score_taiwan = 40;
} else if (job.taiwan_eligible === 'no') {
  score_taiwan = 0;
} else {
  const globalTerms = ['worldwide', 'work from anywhere', 'global remote', 'contractor', 'deel', 'remote.com', 'oyster', 'eor', 'anywhere', 'no location restriction'];
  const apacTerms = ['apac', 'asia pacific', 'asia-pacific'];
  if (globalTerms.some(t => fullText.includes(t)) || job.contractor_possible === 'yes') {
    score_taiwan = 40;
  } else if (apacTerms.some(t => fullText.includes(t))) {
    score_taiwan = 30;
  }
}

// Async score (0–25)
let score_async = 0;
let async_level = 'unknown';
const clearlyAsync = ['async', 'asynchronous', 'async-first', 'async first', 'no meetings', 'low meeting', 'minimal meetings', 'writing-first'];
const flexHours = ['flexible hours', 'flexible schedule', 'set your own hours', 'work when you want', 'flexible working', 'your own pace'];
const distributed = ['distributed team', 'distributed company', 'remote-first', 'remote first', 'fully remote', 'all remote'];
const syncWarning = ['9-5', '9 to 5', 'fixed hours', 'must overlap', 'overlap us hours', 'overlap est', 'overlap pst', 'est required', 'pst required', 'daily standup required', 'core us hours'];

if (clearlyAsync.some(t => fullText.includes(t))) {
  score_async = 25; async_level = 'high';
} else if (flexHours.some(t => fullText.includes(t))) {
  score_async = 20; async_level = 'medium-high';
} else if (distributed.some(t => fullText.includes(t))) {
  score_async = 15; async_level = 'medium';
} else if (fullText.includes('remote')) {
  score_async = 10; async_level = 'low-medium';
}
if (syncWarning.some(t => fullText.includes(t))) {
  score_async = Math.max(0, score_async - 10);
  if (score_async <= 5) async_level = 'low';
}

// Role score (0–25)
let score_role = 0;
let role_category = 'other';
const primaryRoles = [
  'data analyst', 'data scientist', 'business intelligence', 'bi analyst',
  'marketing analyst', 'performance marketing', 'growth analyst', 'growth hacker',
  'ai marketing', 'ai automation', 'ai workflow', 'marketing automation',
  'martech', 'marketing technology', 'analytics engineer', 'analytics manager',
  'product analyst', 'digital analyst', 'reporting analyst', 'machine learning',
  'data engineer', 'creative strategist', 'marketing data'
];
const adjacentRoles = [
  'digital marketing', 'seo specialist', 'paid media', 'ppc specialist',
  'email marketing', 'content strategist', 'operations analyst', 'revenue analyst',
  'ecommerce analyst', 'crm analyst', 'social media manager', 'marketing manager'
];
if (primaryRoles.some(r => titleLower.includes(r) || fullText.includes(r))) {
  score_role = 25; role_category = 'primary';
} else if (adjacentRoles.some(r => titleLower.includes(r) || fullText.includes(r))) {
  score_role = 15; role_category = 'adjacent';
}

// Salary score (0–25)
let score_salary = 0;
const salaryText = (job.salary || '').toLowerCase().replace(/,/g, '');
const numMatches = salaryText.match(/\d+/g);
let monthlyVal = 0;
if (numMatches && numMatches.length > 0) {
  const maxNum = Math.max(...numMatches.map(Number));
  if (salaryText.includes('year') || salaryText.includes('annual') || salaryText.includes('yr') || maxNum > 20000) {
    monthlyVal = Math.round(maxNum / 12);
  } else {
    monthlyVal = maxNum;
  }
}
if (monthlyVal >= 5000) score_salary = 25;
else if (monthlyVal >= 3000) score_salary = 15;
else if (salaryText.length > 2) score_salary = 10;

const score = score_taiwan + score_async + score_role + score_salary;

// Why good fit
const reasons = [];
if (job.taiwan_eligible === 'yes') reasons.push('AI confirmed Taiwan eligible');
if (job.contractor_possible === 'yes') reasons.push('contractor arrangement available');
if (score_taiwan >= 40) reasons.push('worldwide/global remote');
if (score_taiwan === 30) reasons.push('APAC friendly');
if (async_level === 'high') reasons.push('fully async culture');
if (async_level === 'medium-high') reasons.push('flexible hours');
if (role_category === 'primary') reasons.push('matches target role: data/AI/marketing analytics');
if (monthlyVal >= 5000) reasons.push('strong salary ($' + monthlyVal + '/mo)');
if (monthlyVal >= 3000 && monthlyVal < 5000) reasons.push('solid salary ($' + monthlyVal + '/mo)');
const whyGoodFit = reasons.join('; ') || 'Passed all filters — manual review recommended';

return [{
  json: {
    ...job,
    score,
    score_taiwan,
    score_async,
    score_role,
    score_salary,
    async_level,
    role_category,
    why_good_fit: whyGoodFit,
    application_status: score >= 85 ? 'urgent' : 'new',
    notes: ''
  }
}];

const job = $input.item.json;
const title = job.job_title || '';
const company = job.company || '';
const description = (job.description || '').slice(0, 2000);
const whyFit = job.why_good_fit || '';
const roleCategory = job.role_category || '';

const prompt = `Write a short cover letter for Jerry applying to ${title} at ${company}.

Jerry's background:
- Bilingual English and Mandarin (grew up in California and Taiwan)
- Digital marketing background with data science bootcamp training
- Technical skills: Python, SQL, Tableau, Power BI, GA4, Meta Ads, Google Ads
- AI tools: ChatGPT, Claude, Gemini, Cursor
- Experience: dashboards, EDA, machine learning projects, customer segmentation, fraud detection, and marketing analytics
- Performance marketing, SEO, PPC, and marketing automation experience
- Based in Taiwan, looking for async global remote work

Job description excerpt:
${description}

Why this role fits Jerry: ${whyFit}

The letter must:
- Be under 220 words
- Specifically mention how Jerry can help this company:
  * Reduce manual analysis time through automation and AI-assisted workflows
  * Improve reporting speed and data accessibility
  * Connect marketing data to business outcomes
  * Build efficient dashboards and AI workflows
  * Turn messy data into actionable business insights
- Tone: confident, direct, human — not desperate or generic
- Open strong (no 'I am excited to apply')
- Be specific to this role at ${company}
- Mention Taiwan-based async remote availability naturally`;

const apiBody = JSON.stringify({
  model: 'claude-opus-4-7',
  max_tokens: 700,
  messages: [{ role: 'user', content: prompt }]
});

return [{ json: { ...job, _cover_letter_api_body: apiBody } }];

const clHttpResponse = $input.item.json;
const originalJob = $('Prepare Cover Letter').item.json;

let coverLetterText = '';
try {
  if (Array.isArray(clHttpResponse.content) && clHttpResponse.content[0]) {
    coverLetterText = clHttpResponse.content[0].text || '';
  }
} catch(e) { coverLetterText = 'Cover letter generation failed.'; }

const { _cover_letter_api_body, ...cleanJob } = originalJob;

return [{
  json: {
    ...cleanJob,
    cover_letter: coverLetterText,
    has_cover_letter: true
  }
}];

const allItems = $input.all();
const today = new Date().toLocaleDateString('en-US', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: 'Asia/Taipei'
});

if (allItems.length === 0) {
  return [{
    json: {
      subject: `Daily Taiwan Remote Jobs — No new matches today (${today})`,
      body: `<p>No new Taiwan-eligible async remote jobs found today. The search will run again tomorrow at 8:30 AM Taipei time.</p>`,
      job_count: 0,
      alert_count: 0
    }
  }];
}

const jobs = allItems.map(i => i.json).sort((a, b) => (b.score || 0) - (a.score || 0));
const alertJobs = jobs.filter(j => (j.score || 0) >= 85);
const goodJobs = jobs.filter(j => (j.score || 0) >= 70 && (j.score || 0) < 85);
const manualJobs = jobs.filter(j => j.taiwan_eligible === 'unclear' && (j.score || 0) >= 70);

const badge = s => s >= 85 ? '🟢' : s >= 70 ? '🔵' : '⚪';

let html = `<div style="font-family: Arial, sans-serif; max-width: 680px; margin: 0 auto; color: #101828;">`;
html += `<h1 style="font-size:22px; margin-bottom:4px;">🇹🇼 Daily Taiwan Eligible Async Remote Jobs</h1>`;
html += `<p style="color:#6b7280; font-size:14px; margin:0 0 16px;">${today} &nbsp;·&nbsp; <strong>${jobs.length}</strong> job${jobs.length !== 1 ? 's' : ''} passed all filters &nbsp;·&nbsp; <strong>${alertJobs.length}</strong> high-priority alert${alertJobs.length !== 1 ? 's' : ''}</p>`;
html += `<hr style="border:1px solid #e5e7eb; margin:0 0 24px;">`;

if (alertJobs.length > 0) {
  html += `<h2 style="color:#059669; font-size:18px;">🚨 Apply Now — Score 85+ (${alertJobs.length})</h2>`;
  alertJobs.forEach((job, i) => {
    html += `<div style="border:2px solid #059669; border-radius:8px; padding:16px; margin:16px 0; background:#f0fdf4;">`;
    html += `<h3 style="margin:0 0 12px; font-size:16px;">${i + 1}. ${job.job_title}</h3>`;
    html += `<table style="font-size:14px; border-collapse:collapse; width:100%;"><tbody>`;
    html += `<tr><td style="padding:3px 12px 3px 0; color:#6b7280; white-space:nowrap;">Company</td><td><strong>${job.company}</strong></td></tr>`;
    html += `<tr><td style="padding:3px 12px 3px 0; color:#6b7280;">Score</td><td><strong>${job.score}/100</strong></td></tr>`;
    html += `<tr><td style="padding:3px 12px 3px 0; color:#6b7280;">Taiwan Eligible</td><td>${job.taiwan_eligible} — ${job.taiwan_reason || ''}</td></tr>`;
    html += `<tr><td style="padding:3px 12px 3px 0; color:#6b7280;">Async Level</td><td>${job.async_level}</td></tr>`;
    html += `<tr><td style="padding:3px 12px 3px 0; color:#6b7280;">Timezone Risk</td><td>${job.timezone_risk}</td></tr>`;
    html += `<tr><td style="padding:3px 12px 3px 0; color:#6b7280;">Location Risk</td><td>${job.location_risk}</td></tr>`;
    html += `<tr><td style="padding:3px 12px 3px 0; color:#6b7280;">Salary</td><td>${job.salary || 'Not listed'}</td></tr>`;
    html += `<tr><td style="padding:3px 12px 3px 0; color:#6b7280;">Why it fits</td><td>${job.why_good_fit}</td></tr>`;
    html += `</tbody></table>`;
    if (job.cover_letter) {
      html += `<details style="margin-top:12px;"><summary style="cursor:pointer; color:#059669; font-weight:600;">📝 View Cover Letter Draft</summary><div style="margin-top:8px; padding:12px; background:#fff; border-radius:4px; font-size:13px; white-space:pre-wrap;">${job.cover_letter}</div></details>`;
    }
    html += `<p style="margin:14px 0 0;"><a href="${job.job_url}" style="background:#059669; color:#fff; padding:8px 18px; text-decoration:none; border-radius:4px; font-size:14px;">→ Apply Now</a></p>`;
    html += `</div>`;
  });
}

if (goodJobs.length > 0) {
  html += `<h2 style="color:#1a56db; font-size:18px; margin-top:24px;">✅ Good Matches — Score 70–84 (${goodJobs.length})</h2>`;
  goodJobs.slice(0, 12).forEach((job, i) => {
    html += `<div style="border:1px solid #bfdbfe; border-radius:8px; padding:14px; margin:12px 0; background:#eff6ff;">`;
    html += `<h4 style="margin:0 0 6px; font-size:15px;">${i + 1}. ${job.job_title} — <em>${job.company}</em></h4>`;
    html += `<p style="margin:4px 0; font-size:13px; color:#374151;">Score: <strong>${job.score}</strong> &nbsp;·&nbsp; ${job.async_level} async &nbsp;·&nbsp; Salary: ${job.salary || 'N/A'} &nbsp;·&nbsp; ${job.taiwan_eligible} eligible</p>`;
    html += `<p style="margin:4px 0; font-size:13px;">${job.why_good_fit}</p>`;
    html += `<p style="margin:8px 0 0;"><a href="${job.job_url}" style="color:#1a56db; font-size:13px;">→ View Job</a></p>`;
    html += `</div>`;
  });
}

if (manualJobs.length > 0) {
  html += `<h2 style="color:#d97706; font-size:18px; margin-top:24px;">⚠️ Manual Check Needed (${manualJobs.length})</h2>`;
  html += `<p style="font-size:14px;">Taiwan eligibility is unclear — review these yourself:</p><ul>`;
  manualJobs.slice(0, 8).forEach(job => {
    html += `<li style="margin:6px 0;"><a href="${job.job_url}">${job.job_title} at ${job.company}</a> — Score: ${job.score} — ${job.taiwan_reason || 'Eligibility unclear'}</li>`;
  });
  html += `</ul>`;
}

html += `<hr style="border:1px solid #e5e7eb; margin:28px 0 16px;">`;
html += `<p style="color:#9ca3af; font-size:12px; margin:0;">`;
html += `Next run: tomorrow 8:30 AM Asia/Taipei &nbsp;·&nbsp; Taiwan Job Hunter v1.0<br>`;
html += `${alertJobs.length} urgent &nbsp;·&nbsp; ${goodJobs.length} good &nbsp;·&nbsp; ${manualJobs.length} manual check</p>`;
html += `</div>`;

const subject = alertJobs.length > 0
  ? `🚨 ${alertJobs.length} URGENT — Taiwan Remote Jobs (${jobs.length} total) — ${today}`
  : `🇹🇼 ${jobs.length} Taiwan Remote Match${jobs.length !== 1 ? 'es' : ''} — ${today}`;

return [{ json: { subject, body: html, job_count: jobs.length, alert_count: alertJobs.length } }];
